UPDATE members
SET role = #{role},
    status = #{status},
    role_updated_at = #{roleUpdatedAt},
    version = version + 1
WHERE id = #{memberId}
  AND version = #{expectedVersion}
  AND (
      SELECT COUNT(*) FROM (
          SELECT id FROM members
          WHERE role = 'ADMIN' AND status = 'ACTIVE'
      ) active_admins
      WHERE active_admins.id <> #{memberId}
  ) > 0
